examples.example:
// Two editElement edits, one per prop. Note the `__wwtype: 'js'` wrapper around the Chart.js config — without it, the value will not persist.
edits: [
  {
    path: 'content.default.data',
    value: {
      __wwtype: 'js',
      code: "return { labels: ['Organic','Paid','Social','Referral'], datasets: [{ label: 'Users', data: [45, 30, 20, 5], backgroundColor: ['#0066FF','#10B981','#F59E0B','#6B7280'] }] }",
      defaultValue: {}
    }
  },
  {
    path: 'content.default.options',
    value: {
      __wwtype: 'js',
      code: "return { cutout: '60%', plugins: { legend: { position: 'bottom' } } }",
      defaultValue: {}
    }
  }
]

// Single editElement edit on `content.default.data`. Replace each token UID with the value returned by `searchTokens` for the brand color you want. The hex strings after `||` are fallbacks if a token is missing/unset.
edits: [{
  path: 'content.default.data',
  value: {
    __wwtype: 'js',
    code: "return { labels: ['Organic','Paid','Social','Referral'], datasets: [{ label: 'Users', data: [45,30,20,5], backgroundColor: [globalContext.colors['fe35a464-...'] || '#0066FF', globalContext.colors['592f1669-...'] || '#10B981', globalContext.colors['cb3b023b-...'] || '#F59E0B', globalContext.colors['7eca1434-...'] || '#EF4444'] }] }",
    defaultValue: {}
  }
}]
